const cwd="/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne";
const cmds=[
"nl -ba HartshorneLib.lean | sed -n '90,130p'",
"\"$HORIZON_BIN\" graph -p Hartshorne search exists_localRatioOpen_orderAt_eq_of_basePointFree --json",
"\"$HORIZON_BIN\" graph -p Hartshorne search exists_divisorSection_orderAt_eq_of_basePointFree --json",
"\"$HORIZON_BIN\" graph -p Hartshorne search gluedCoordinateChartMap_eq_map --json"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:cwd,yield_time_ms:10000,max_output_tokens:15000})));
rs.forEach((r,i)=>text(`===${i}===\n${r.output}`));

const jobs = [
  ["reverse_imports", "rg -n --glob '*.lean' '^import HartshorneLib\\.Chapter4(BasePointFreeLocalJump|BasePointFreeDenominatorOpen)' .; rg -n 'Chapter4BasePointFree(LocalJump|DenominatorOpen)' HartshorneLib.lean || true"],
  ["forbidden_scan", "rg -n '\\bsorry\\b|\\badmit\\b|(^|[[:space:]])axiom[[:space:]]|unsafe|implemented_by' HartshorneLib/Chapter4BasePointFreeLocalJump.lean HartshorneLib/Chapter4BasePointFreeDenominatorOpen.lean || true"],
  ["root_lines", "nl -ba HartshorneLib.lean | sed -n '96,118p'"],
  ["current_status", "\"$HORIZON_GIT\" status --short -- FormalizedSources/Curves/Hartshorne"]
];
const rs = await Promise.all(jobs.map(async ([name,cmd]) => {
  const r = await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne",yield_time_ms:10000,max_output_tokens:10000});
  return `===== ${name} =====\n${r.output}`;
}));
rs.forEach(text);
